function getStockLevel(stock) {
  if (stock >= 10) return '충분';
  else if (stock >= 1) return '부족';
  else return '품절';
}

function getDelayLevel(minutes) {
  if (minutes >= 120) return '심각';
  else if (minutes >= 60) return '지연';
  else if (minutes >= 1) return '주의';
  else return '정상';
}
